'use client';

import { useMemo, useRef, useState, type FormEvent } from 'react';

type FormState = {
  displayName: string;
  email: string;
  password: string;
};

type ValidationErrors = Partial<Record<keyof FormState, string>>;

const initialForm: FormState = {
  displayName: '',
  email: '',
  password: '',
};

const validateField = (name: keyof FormState, value: string): string => {
  if (name === 'displayName') {
    if (!value.trim()) return 'Display name is required.';
    if (value.trim().length < 2 || value.trim().length > 50) {
      return 'Display name must be 2-50 characters.';
    }
  }

  if (name === 'email') {
    if (!value.trim()) return 'Email is required.';
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
      return 'Please enter a valid email address.';
    }
  }

  if (name === 'password' && value) {
    if (value.length < 8) return 'Password must be at least 8 characters.';
    if (!/\d/.test(value)) return 'Password must contain at least one number.';
  }

  return '';
};

const validateForm = (values: FormState): ValidationErrors => {
  const nextErrors: ValidationErrors = {};

  (Object.keys(values) as Array<keyof FormState>).forEach((field) => {
    const error = validateField(field, values[field]);
    if (error) nextErrors[field] = error;
  });

  return nextErrors;
};

const fakeApiUpdate = async (): Promise<void> => {
  await new Promise((resolve) => setTimeout(resolve, 400));
  if (Math.random() < 0.35) {
    throw new Error('The update failed. Please try again.');
  }
};

export default function SettingsForm() {
  const [formState, setFormState] = useState<FormState>(initialForm);
  const [touched, setTouched] = useState<Record<keyof FormState, boolean>>({
    displayName: false,
    email: false,
    password: false,
  });
  const [errors, setErrors] = useState<ValidationErrors>({});
  const [submitting, setSubmitting] = useState(false);
  const [bannerMessage, setBannerMessage] = useState<string | null>(null);
  const [toastMessage, setToastMessage] = useState<string | null>(null);
  const fieldRefs = useRef<Record<keyof FormState, HTMLInputElement | null>>({
    displayName: null,
    email: null,
    password: null,
  });

  const visibleErrors = useMemo(() => {
    const next: ValidationErrors = {};
    (Object.keys(formState) as Array<keyof FormState>).forEach((field) => {
      if (touched[field]) {
        next[field] = errors[field] || undefined;
      }
    });
    return next;
  }, [errors, formState, touched]);

  const isFormValid = useMemo(() => {
    const validationErrors = validateForm(formState);
    return Object.keys(validationErrors).length === 0;
  }, [formState]);

  const handleBlur = (field: keyof FormState) => {
    setTouched((current) => ({ ...current, [field]: true }));
    const message = validateField(field, formState[field]);
    setErrors((current) => ({ ...current, [field]: message || undefined }));
  };

  const handleChange = (field: keyof FormState, value: string) => {
    setFormState((current) => ({ ...current, [field]: value }));
    setBannerMessage(null);
    setToastMessage(null);
    if (touched[field]) {
      const message = validateField(field, value);
      setErrors((current) => ({ ...current, [field]: message || undefined }));
    }
  };

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setBannerMessage(null);
    setToastMessage(null);
    const nextErrors = validateForm(formState);
    setErrors(nextErrors);
    setTouched({ displayName: true, email: true, password: true });

    if (Object.keys(nextErrors).length > 0) {
      const firstInvalidField = (Object.keys(nextErrors)[0] || 'displayName') as keyof FormState;
      fieldRefs.current[firstInvalidField]?.focus();
      return;
    }

    setSubmitting(true);

    try {
      await fakeApiUpdate();
      setToastMessage('Your profile was updated successfully.');
    } catch {
      setBannerMessage('We could not update your profile. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <main className="min-h-screen bg-slate-50 px-4 py-10 text-slate-900 sm:px-6 lg:px-8">
      <div className="mx-auto max-w-3xl rounded-3xl border border-slate-200 bg-white p-6 shadow-sm sm:p-8">
        <div className="mb-8">
          <p className="text-sm font-semibold uppercase tracking-[0.3em] text-indigo-600">Settings</p>
          <h1 className="mt-2 text-3xl font-semibold text-slate-900">Update profile information</h1>
          <p className="mt-3 text-sm text-slate-600 sm:text-base">
            Change how your account appears and keep your credentials secure.
          </p>
        </div>

        {bannerMessage ? (
          <div className="mb-6 rounded-2xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700" role="alert">
            {bannerMessage}
          </div>
        ) : null}

        <form className="space-y-6" onSubmit={handleSubmit} noValidate>
          <div>
            <label htmlFor="displayName" className="mb-2 block text-sm font-medium text-slate-700">
              Display name
            </label>
            <input
              id="displayName"
              name="displayName"
              ref={(element) => {
                fieldRefs.current.displayName = element;
              }}
              value={formState.displayName}
              onChange={(event) => handleChange('displayName', event.target.value)}
              onBlur={() => handleBlur('displayName')}
              aria-invalid={Boolean(visibleErrors.displayName)}
              aria-describedby={visibleErrors.displayName ? 'displayName-error' : undefined}
              className="w-full rounded-xl border border-slate-300 px-4 py-3 outline-none transition focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100"
            />
            {visibleErrors.displayName ? (
              <p id="displayName-error" className="mt-2 text-sm text-red-600">
                {visibleErrors.displayName}
              </p>
            ) : null}
          </div>

          <div>
            <label htmlFor="email" className="mb-2 block text-sm font-medium text-slate-700">
              Email address
            </label>
            <input
              id="email"
              name="email"
              type="email"
              ref={(element) => {
                fieldRefs.current.email = element;
              }}
              value={formState.email}
              onChange={(event) => handleChange('email', event.target.value)}
              onBlur={() => handleBlur('email')}
              aria-invalid={Boolean(visibleErrors.email)}
              aria-describedby={visibleErrors.email ? 'email-error' : undefined}
              className="w-full rounded-xl border border-slate-300 px-4 py-3 outline-none transition focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100"
            />
            {visibleErrors.email ? (
              <p id="email-error" className="mt-2 text-sm text-red-600">
                {visibleErrors.email}
              </p>
            ) : null}
          </div>

          <div>
            <label htmlFor="password" className="mb-2 block text-sm font-medium text-slate-700">
              Password
            </label>
            <input
              id="password"
              name="password"
              type="password"
              ref={(element) => {
                fieldRefs.current.password = element;
              }}
              value={formState.password}
              onChange={(event) => handleChange('password', event.target.value)}
              onBlur={() => handleBlur('password')}
              aria-invalid={Boolean(visibleErrors.password)}
              aria-describedby={visibleErrors.password ? 'password-error' : undefined}
              className="w-full rounded-xl border border-slate-300 px-4 py-3 outline-none transition focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100"
              placeholder="Leave blank to keep current password"
            />
            {visibleErrors.password ? (
              <p id="password-error" className="mt-2 text-sm text-red-600">
                {visibleErrors.password}
              </p>
            ) : null}
          </div>

          <div className="flex flex-col gap-3 rounded-2xl border border-slate-200 bg-slate-50 p-4 sm:flex-row sm:items-center sm:justify-between">
            <div>
              <p className="font-medium text-slate-900">Ready to save?</p>
              <p className="text-sm text-slate-600">Your changes will be applied after a brief validation step.</p>
            </div>
            <button
              type="submit"
              disabled={!isFormValid || submitting}
              className="rounded-xl bg-indigo-600 px-5 py-3 font-medium text-white transition hover:bg-indigo-700 disabled:cursor-not-allowed disabled:bg-slate-300"
            >
              {submitting ? 'Saving...' : 'Save changes'}
            </button>
          </div>

          {toastMessage ? (
            <div className="rounded-2xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-700" role="status">
              {toastMessage}
            </div>
          ) : null}
        </form>
      </div>
    </main>
  );
}
